// TETHER — tools/bundle.js
// Bundles levels/*.json into public/js/core/leveldata.js (a committed ES module).
// Zero npm deps. Node 20+.
//
//   node tools/bundle.js            # regenerate leveldata.js
//
// The generated module is plain data (no fetches at runtime). This is the only
// path by which level files enter the shipped site.

import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const levelsDir = join(root, 'levels');
const outFile = join(root, 'public/js/core/leveldata.js');

function loadLevels() {
  const files = readdirSync(levelsDir)
    .filter((f) => f.endsWith('.json'))
    .sort();
  if (files.length === 0) throw new Error('no levels found in levels/');
  const levels = files.map((f) => {
    const raw = readFileSync(join(levelsDir, f), 'utf8');
    const level = JSON.parse(raw);
    if (!level.id) throw new Error(`${f}: missing "id"`);
    return level;
  });
  levels.sort((a, b) => (a.world - b.world) || (a.index - b.index));
  // enforce uniqueness
  const ids = new Set();
  for (const l of levels) {
    if (ids.has(l.id)) throw new Error(`duplicate level id: ${l.id}`);
    ids.add(l.id);
  }
  return levels;
}

// Light structural check before committing data (full schema lives in validate.js).
function check(level) {
  if (!Array.isArray(level.grid) || level.grid.length === 0) throw new Error(`${level.id}: grid must be a non-empty array`);
  const w = level.grid[0].length;
  for (const row of level.grid) if (row.length !== w) throw new Error(`${level.id}: ragged grid (row lengths differ)`);
  const allowed = new Set(['#', '=', '^', 'M', 'L', 'P', 'G', '.', ' ']);
  for (const row of level.grid) for (const ch of row) if (!allowed.has(ch)) throw new Error(`${level.id}: unexpected char "${ch}"`);
  const flat = level.grid.join('');
  if (!flat.includes('P')) throw new Error(`${level.id}: no spawn (P)`);
  if (!flat.includes('G')) throw new Error(`${level.id}: no gate (G)`);
  const motes = (flat.match(/M/g) || []).length + (level.entities || []).filter((e) => e.type === 'mote').length;
  if (motes < 3 || motes > 5) throw new Error(`${level.id}: must have 3-5 motes (has ${motes})`);
  const platforms = (level.entities || []).filter((e) => e.type === 'platform');
  if (platforms.length > 3) throw new Error(`${level.id}: too many moving platforms (max 3)`);
  return motes;
}

const levels = loadLevels();
let total = 0;
for (const l of levels) total += check(l);

const header = `// AUTO-GENERATED by tools/bundle.js — do not edit by hand.
// Source of truth: levels/*.json. Regenerate with: npm run bundle.
// This is plain committed data so the shipped site never fetches level files.
`;

const body = `export const LEVELS = ${JSON.stringify(levels, null, 2)};
`;

writeFileSync(outFile, header + body);
console.log(`bundle: ${levels.length} levels -> public/js/core/leveldata.js (${total} motes)`);
